<template>
  <div class="app-container gift-management">
    <div class="page-title"><div><h2>赠品管理</h2><p>先配置店铺组，再关联可复用的策略组；清晰查看每家店铺的赠品执行路径。</p></div><el-button v-hasPermi="['order:gift:config']" type="primary" @click="edit()"><i class="el-icon-plus" aria-hidden="true"/>新增公共策略组</el-button></div>
    <el-tabs v-model="tab" @tab-click="tabChanged"><el-tab-pane label="店铺组与执行顺序" name="shops"><gift-shop-groups :scopes="scopes" :groups="groups" :shops="shops" :types="types" :initial-scope="$route.query.scopeId" @changed="load" @edit-strategy="edit" @new-strategy="edit(null,$event)"/></el-tab-pane>
    <el-tab-pane label="公共策略库" name="groups"><el-alert title="策略库维护赠送条件、活动时间和售后方式；适用店铺、执行顺序和命中后是否继续，在“店铺组与执行顺序”中配置。编辑公共策略会影响所有关联店铺组的后续新转单。" :closable="false" type="info" show-icon/>
      <el-table v-loading="loading" :data="groups" style="margin-top:18px" empty-text="暂无策略组，请新增公共策略组后关联店铺组"><el-table-column label="公共策略组 / 付款范围" min-width="280"><template slot-scope="s"><strong>{{ s.row.name }}</strong><div class="hint">{{ s.row.policy.start_time }} 至 {{ s.row.policy.end_time }}</div></template></el-table-column><el-table-column label="组内规则 · 从上到下" min-width="280"><template slot-scope="s"><div v-for="(r,i) in s.row.policy.rules" :key="r.key">{{ i+1 }}. {{ r.name }} · {{ types[r.type] }}<div class="hint">{{ r.max_count?'活动累计上限 '+r.max_count+' 次':'活动累计不限' }}<span v-if="(s.row.quota_usage||{})[r.key]"> · 已占用 {{ s.row.quota_usage[r.key].used_count }} 次</span> · {{ r.stop?'实际赠送后结束本组':'继续本组下一条' }}</div></div></template></el-table-column><el-table-column label="关联店铺组 / 影响范围" min-width="230"><template slot-scope="s"><el-tag v-for="scope in usages(s.row.id)" :key="scope.id" size="small" style="margin:3px">{{ scope.name }}{{ scope.enabled?'':'（停用）' }}</el-tag><span v-if="!usages(s.row.id).length" class="hint">未关联店铺组，不参与赠送</span><div class="hint">{{ usages(s.row.id).length }} 个店铺组 · {{ affectedShops(s.row.id) }} 家店铺</div></template></el-table-column><el-table-column label="售后处理" min-width="185"><template slot-scope="s"><div>未发：取消 / 先截单后取消</div><div>已发：{{ s.row.policy.shipped_policy==='KEEP'?'允许保留':'安排退回' }}</div></template></el-table-column><el-table-column label="状态 / 版本" width="120"><template slot-scope="s"><el-tag :type="s.row.enabled?'success':'info'">{{ s.row.enabled?'已启用':'已停用' }}</el-tag><div class="hint">版本 {{ s.row.revision }}</div></template></el-table-column><el-table-column label="操作" width="130" fixed="right"><template slot-scope="s"><el-button v-hasPermi="['order:gift:config']" type="text" @click="edit(s.row)">编辑</el-button><el-button v-hasPermi="['order:gift:config']" type="text" @click="copy(s.row)">复制</el-button></template></el-table-column></el-table>
    </el-tab-pane><el-tab-pane label="赠送与售后记录" name="records"><el-form inline size="small" @submit.native.prevent="loadRecords"><el-form-item><el-input v-model="query.number" clearable placeholder="OMS 单号 / 平台单号"/></el-form-item><el-button type="primary" @click="query.pageNum=1;loadRecords()">查询</el-button></el-form><el-table v-loading="loading" :data="records"><el-table-column label="订单" min-width="320"><template slot-scope="s"><el-link type="primary" @click="open(s.row.order_id)">{{ s.row.order_sn }}</el-link><div class="hint">平台 {{ s.row.platform_tid }} · 店铺 {{ shopNames([s.row.channel_id]) }}</div></template></el-table-column><el-table-column label="原赠品" min-width="240"><template slot-scope="s"><div v-for="g in s.row.gifts" :key="g.sku_sn">{{ g.sku_sn }} × {{ g.quantity }} {{ g.sales_unit }}</div></template></el-table-column><el-table-column label="当前处理提示" min-width="270"><template slot-scope="s"><span :class="s.row.gift_block_reason?'warning':''">{{ s.row.gift_block_reason||s.row.last_error||'查看赠品详情了解发货及追退进度' }}</span></template></el-table-column><el-table-column prop="create_time" label="生成时间" width="180"/><el-table-column label="操作" width="110"><template slot-scope="s"><el-button type="text" @click="open(s.row.order_id)">处理赠品</el-button></template></el-table-column></el-table><pagination v-show="total>0" :total="total" :page.sync="query.pageNum" :limit="20" @pagination="loadRecords"/></el-tab-pane><el-tab-pane label="订单试算" name="preview"><el-alert title="仅用当前发布规则及剩余额度试算，不占赠送次数、不占库存；实际转单以并发申请结果为准。已生成赠品的订单仍采用原策略快照。" :closable="false" type="info"/><el-form inline size="small" style="margin-top:18px" @submit.native.prevent="preview"><el-form-item label="业务订单"><el-input v-model="previewId" placeholder="输入 OMS 单号 / 平台单号"/></el-form-item><el-button type="primary" :loading="loading" @click="preview">试算当前规则</el-button></el-form><template v-if="calculation"><el-alert :title="`试算赠品：${(calculation.gifts||[]).map(g=>g.sku_sn+' × '+g.quantity).join('，')||'未命中赠品'}`" :closable="false" type="success"/><div v-if="calculation.shop_scope" class="trace"><strong>店铺 {{ shopNames([calculation.shop_scope.channel_id]) }}</strong><div v-for="scope in calculation.shop_scope.shop_groups" :key="scope.id">{{ scope.name }} · {{ scope.enabled?'已启用':'已停用，不参与赠送' }}<div v-for="g in scope.executions" :key="g.group_id" class="hint">{{ g.sequence }}. {{ g.name }} · {{ g.enabled?'已启用':'已停用，跳过' }} · 命中后{{ g.continue_after_match?'继续下一组':'停止后续组' }}</div></div><div v-if="!calculation.shop_scope.shop_groups.some(s=>s.enabled)">未归属启用的赠品店铺组，不参与赠送。</div></div><div v-for="g in calculation.trace" :key="g.shop_group_id+'-'+g.group_id" class="trace"><strong>{{ g.shop_group_name }} / 第 {{ g.priority }} 组 · {{ g.name }}：{{ g.reason }}</strong><div v-for="r in g.rules" :key="r.key">{{ r.matched?'✓':'—' }} {{ r.name }}：{{ r.reason }}<span v-if="!r.skipped"> · 门槛口径 {{ r.basis_quantity }} 件 / ¥{{ r.basis_amount }}</span></div></div></template></el-tab-pane></el-tabs>
    <el-dialog title="订单赠品与售后处理" :visible.sync="detailVisible" width="95%" append-to-body top="3vh"><order-gifts v-if="detailVisible" :order-id="selectedOrder" @changed="loadRecords"/><span slot="footer"><el-button @click="detailVisible=false">关闭</el-button></span></el-dialog>
  </div>
</template>
<script>
import * as api from '@/api/order/gift'
import GiftShopGroups from './GiftShopGroups'
import OrderGifts from './OrderGifts'
export default {
  name:'GiftManagement',components:{OrderGifts,GiftShopGroups},
  data:()=>({tab:'shops',groups:[],scopes:[],shops:[],records:[],total:0,loading:false,loaded:false,query:{number:'',pageNum:1},previewId:'',calculation:null,types:{AMOUNT:'满额赠',PRODUCT:'指定商品赠',MULTIPLE:'买多赠多',TIER:'阶梯赠'},detailVisible:false,selectedOrder:null}),
  async created(){this.shops=(await api.giftCatalog()).data;await this.load();this.loaded=true;if(this.$route.query.orderId)this.open(this.$route.query.orderId)},
  activated(){if(this.loaded)this.load()},
  methods:{
    async load(){this.loading=true;try{const result=await Promise.all([api.giftGroups(),api.giftShopGroups()]);this.groups=result[0].data;this.scopes=result[1].data}finally{this.loading=false}},
    async loadRecords(){this.loading=true;try{const d=(await api.giftRecords(this.query)).data;this.records=d.rows;this.total=d.total}finally{this.loading=false}},
    tabChanged(){if(this.tab==='records')this.loadRecords()},
    shopNames(ids){return (ids||[]).map(id=>{const s=this.shops.find(s=>Number(s.channel_id)===Number(id));return s?s.channel_name:`店铺 ${id}`}).join('、')},
    usages(id){return this.scopes.filter(s=>s.links.some(l=>Number(l.group_id)===Number(id)))},
    affectedShops(id){return new Set(this.usages(id).flatMap(s=>s.channels)).size},
    edit(row,scope){this.$router.push({path:'/oms-order/gift-editor/index',query:{...(row&&row.id?{id:String(row.id)}:{}),...(scope?{scope:String(scope)}:{})}})},
    copy(row){this.$router.push({path:'/oms-order/gift-editor/index',query:{copy:String(row.id)}})},
    open(id){this.selectedOrder=id;this.detailVisible=true},
    async preview(){if(!this.previewId.trim())return this.$message.warning('请输入 OMS 单号或平台单号');this.loading=true;try{this.calculation=(await api.giftPreviewNumber(this.previewId.trim())).data}finally{this.loading=false}}
  }
}
</script>
<style scoped>.page-title,.rule-heading{display:flex;justify-content:space-between;align-items:center}.page-title h2{margin:0}.page-title p,.hint{font-size:12px;color:#8491a3;line-height:1.8}.two{display:grid;grid-template-columns:1fr 1fr}.editor{margin-top:20px}.rule,.trace{border:1px solid #dfe6ef;border-radius:8px;padding:18px;margin:14px 0}.rule-heading{margin-bottom:12px}.gift-edit{display:flex;align-items:center;gap:12px;margin-bottom:8px}.tier{margin:14px 0;padding:14px;background:#f5f8fc}.warning{color:#a76b13}.trace>div{padding:8px 0;font-size:13px}@media(max-width:760px){.page-title{flex-direction:column;align-items:flex-start;gap:12px}.two{grid-template-columns:minmax(0,1fr)}}</style>
